#!/usr/bin/env swift
// Source/release build tool; generated bytes are embedded, never downloaded at runtime.
import Foundation
import CryptoKit

struct InvalidArtifact: Error { let reason: String }
func require(_ condition: Bool, _ reason: String) throws {
    if !condition { throw InvalidArtifact(reason: reason) }
}
func hash(_ data: Data) -> String { SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined() }
func number(_ data: Data, _ offset: Int, _ count: Int) throws -> UInt64 {
    try require(offset >= 0 && count > 0 && offset <= data.count && count <= data.count - offset, "truncated ELF metadata")
    return (0..<count).reduce(0) { $0 | UInt64(data[offset + $1]) << ($1 * 8) }
}
func verify(_ data: Data, machine: UInt64) throws {
    try require(data.count >= 64 && data.count <= 2 * 1024 * 1024, "invalid ELF size")
    try require(Array(data.prefix(7)) == [0x7f, 69, 76, 70, 2, 1, 1], "expected ELF64 little-endian version 1")
    try require(try number(data, 16, 2) == 2 && number(data, 18, 2) == machine && number(data, 20, 4) == 1, "wrong ELF executable machine/version")
    try require(try number(data, 52, 2) == 64, "invalid ELF header size")
    let tableValue = try number(data, 32, 8)
    try require(tableValue <= UInt64(data.count), "invalid program table offset")
    let table = Int(tableValue), entry = Int(try number(data, 54, 2)), count = Int(try number(data, 56, 2))
    try require(entry == 56 && count > 0 && count <= 128 && table >= 64 && count * entry <= data.count - table, "invalid program table bounds")
    var executable = false
    let entryPoint = try number(data, 24, 8)
    for index in 0..<count {
        let p = table + index * entry, kind = try number(data, p, 4)
        // Reject PT_DYNAMIC entirely: no DT_NEEDED or interpreter is permissible.
        try require(kind != 2 && kind != 3, "dynamic dependency/interpreter is forbidden")
        let offset = try number(data, p + 8, 8), size = try number(data, p + 32, 8)
        try require(offset <= UInt64(data.count) && size <= UInt64(data.count) - offset, "truncated program segment")
        if kind == 1 {
            let memory = try number(data, p + 40, 8), address = try number(data, p + 16, 8)
            try require(memory >= size && address <= UInt64.max - memory, "invalid load segment")
            if try number(data, p + 4, 4) & 1 != 0 && entryPoint >= address && entryPoint - address < size { executable = true }
        }
    }
    try require(executable, "no executable entry-point segment")
    let sections = try number(data, 40, 8), sectionSize = try number(data, 58, 2), sectionCount = try number(data, 60, 2)
    try require(sections <= UInt64(data.count) && sectionCount <= 4096 && (sectionCount == 0 || sectionSize == 64)
        && sectionSize * sectionCount <= UInt64(data.count) - sections, "invalid section table bounds")
}
struct Artifact: Codable {
    let target: String
    let protocolVersion: Int
    let sourceSHA256: String
    let toolchain: String
    let toolchainArchiveSHA256: [String: String]
    let size: Int
    let sha256: String
}
do {
    try require(CommandLine.arguments.count == 4, "usage: swift scripts/prepare-guest-credential-assets.swift RAW_ROOT OUTPUT_SWIFT SOURCE_C")
    let root = URL(fileURLWithPath: CommandLine.arguments[1], isDirectory: true)
    let output = URL(fileURLWithPath: CommandLine.arguments[2])
    let sourceHash = hash(try Data(contentsOf: URL(fileURLWithPath: CommandLine.arguments[3])))
    let pins = ["macos-arm64": "3cc2bab367e185cdfb27501c4b30b1b0653c28d9f73df8dc91488e66ece5fa6b",
                "linux-amd64": "02aa270f183da276e5b5920b1dac44a63f1a49e55050ebde3aecc9eb82f93239"]
    var artifacts: [Artifact] = [], payloads: [String] = []
    for (directory, target, machine) in [("linux-arm64", "linux/arm64", UInt64(183)), ("linux-amd64", "linux/amd64", UInt64(62))] {
        let data = try Data(contentsOf: root.appendingPathComponent("\(directory)/adevcontainer-git-relay"))
        try verify(data, machine: machine)
        artifacts.append(Artifact(target: target, protocolVersion: 1, sourceSHA256: sourceHash,
            toolchain: "zig-0.15.2", toolchainArchiveSHA256: pins, size: data.count, sha256: hash(data)))
        payloads.append(data.base64EncodedString())
    }
    let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys, .prettyPrinted, .withoutEscapingSlashes]
    let manifest = try encoder.encode(artifacts)
    // Every input is verified before either output is replaced. No date/absolute source path.
    var generated = "// Generated by scripts/prepare-guest-credential-assets.swift; do not edit.\n"
    generated += "enum GuestGitCredentialEmbeddedAssets {\n    static let protocolVersion = 1\n"
    generated += "    static let manifestBase64 = \"\(manifest.base64EncodedString())\"\n"
    for (index, name) in ["arm64", "amd64"].enumerated() {
        generated += "    static let \(name)Base64 = \"\(payloads[index])\"\n"
        generated += "    static let \(name)SHA256 = \"\(artifacts[index].sha256)\"\n"
    }
    generated += "}\n"
    try FileManager.default.createDirectory(at: output.deletingLastPathComponent(), withIntermediateDirectories: true)
    try manifest.write(to: root.appendingPathComponent("manifest.json"), options: .atomic)
    try Data(generated.utf8).write(to: output, options: .atomic)
    print("Verified embedded static guest assets (arm64, amd64), protocol 1")
} catch {
    let reason = (error as? InvalidArtifact)?.reason ?? "could not read/write guest artifacts"
    FileHandle.standardError.write(Data("Guest asset preparation failed: \(reason). Fix inputs and rerun sh scripts/build-guest-credential-relay.sh.\n".utf8))
    exit(1)
}
